// p6/main.tx —— gui 模板（taixu init）：窗口、文字、按钮与点击计数。
// 需要外部 GUI 库 taixu-gui（github.com/yockii/taixu-gui）：设环境变量 TAIXU_GUI_ROOT 为它的 src 目录，或把它放在
// 编译器同级的 taixu-gui/。Windows 上 `taixu run main.tx` 开窗；发布用 `taixu build main.tx --out dist --subsystem=windows`
// （启动不带控制台）。Linux、macOS 的真窗随 GUI 库后续版本，此前程序退回脚本窗、立即结束。
import { Button, button, Canvas, paintText, paintTextWidth, drawButtonC } from "gui/components";
import { appNew, appClose, pump, onClick, onResize, hitZone, defaultSpec } from "gui/app";
import { EventRecord } from "std/events";
import { surfaceOpenDip, surfaceClose, surfaceClear, windowPresent } from "gui/surface";
import { fontEmbedded, fontFree, textCanvasK } from "gui/text";

const BTN: int = 1;

struct Model {
    count: int,
    surface: int,
    btn: Ref<Button>,
}

function render(cv: Ref<Canvas>, w: int, h: int, m: Ref<Model>): void {
    surfaceClear(cv.h, 0x202040);
    paintText(cv, (w - paintTextWidth(cv, "p6")) / 2, 16, 0xFFFFFF, "p6");
    paintText(cv, 16, 48, 0xC0C8E0, "点击次数：" + toStr(m.count));
    m.btn.x = (w - m.btn.w) / 2;
    m.btn.y = h - m.btn.h - 16;
    drawButtonC(cv, m.btn);
}

export function main(args: []string): int {
    args;
    const m: Ref<Model> = new Model { count: 0, surface: 0, btn: button(BTN, 0, 0, 80, 24, "点我") };
    const spec = defaultSpec("p6", 240, 140);
    const app = appNew(spec);
    m.surface = surfaceOpenDip(spec.w, spec.h, app.k) catch (e) {
        print("开不了绘制面：" + e.message);
        appClose(app);
        return 1;
    };
    const font = fontEmbedded() catch (e) {
        print("载入字体失败：" + e.message);
        appClose(app);
        surfaceClose(m.surface);
        return 1;
    };
    onClick(app, BTN, (rec: EventRecord): void => {
            m.count = m.count + 1;
        });
    onResize(app, (w: int, h: int): void => {
            surfaceClose(m.surface);
            m.surface = surfaceOpenDip(w, h, app.k) catch 0;
        });
    while (app.running) {
        const live: bool = pump(app, 16);
        if (app.dirty) {
            const cv = textCanvasK(m.surface, app.w, app.h, font.handle, 14, app.k);
            render(cv, app.w, app.h, m);
            hitZone(app, BTN, m.btn.x, m.btn.y, m.btn.w, m.btn.h);
            windowPresent(app.hwnd, m.surface);
            app.dirty = false;
        }
        if (!live) {
            break;
        }
    }
    print("点击了 " + toStr(m.count) + " 次");
    fontFree(font);
    appClose(app);
    surfaceClose(m.surface);
    return 0;
}
